import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'pending' | 'over' | 'archived';

type Project = {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: ProjectStatus;
};

const STATUS_META: Record<
  ProjectStatus,
  { label: string; tone: 'success' | 'warning' | 'danger' | 'default' }
> = {
  active: { label: 'Активен', tone: 'success' },
  pending: { label: 'Ожидает', tone: 'warning' },
  over: { label: 'Превышен', tone: 'danger' },
  archived: { label: 'В архиве', tone: 'default' },
};

const STATUS_ORDER: ProjectStatus[] = ['active', 'pending', 'over', 'archived'];

const PAGE_SIZE = 5;

const PROJECTS: Project[] = [
  { id: 'p-01', name: 'Платёжный шлюз', used: 412, quota: 500, status: 'active' },
  { id: 'p-02', name: 'Мобильное приложение для курьеров', used: 180, quota: 400, status: 'active' },
  { id: 'p-03', name: 'Аналитика складских остатков', used: 640, quota: 600, status: 'over' },
  { id: 'p-04', name: 'Портал самообслуживания', used: 95, quota: 300, status: 'pending' },
  { id: 'p-05', name: 'Сервис уведомлений', used: 288, quota: 320, status: 'active' },
  { id: 'p-06', name: 'Миграция биллинга', used: 510, quota: 450, status: 'over' },
  { id: 'p-07', name: 'Внутренний поиск', used: 120, quota: 250, status: 'pending' },
  { id: 'p-08', name: 'Отчётность для бухгалтерии', used: 60, quota: 200, status: 'archived' },
  { id: 'p-09', name: 'Пилот рекомендаций', used: 340, quota: 350, status: 'active' },
  { id: 'p-10', name: 'Экспорт данных партнёрам', used: 25, quota: 150, status: 'archived' },
  { id: 'p-11', name: 'Онбординг новых команд', used: 210, quota: 240, status: 'pending' },
  { id: 'p-12', name: 'Шина интеграций', used: 700, quota: 700, status: 'over' },
];

export default function ProjectSpendPanel() {
  const [statuses, setStatuses] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => (statuses.length === 0 ? PROJECTS : PROJECTS.filter((p) => statuses.includes(p.status))),
    [statuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const toggleStatus = (status: ProjectStatus) => {
    setStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setStatuses([]);
    setPage(1);
  };

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <header style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: '20px',
            color: 'var(--jx-text)',
          }}
        >
          Расход по проектам
        </h2>
        <p style={{ margin: 0, fontSize: '14px', color: 'var(--jx-text-2)' }}>
          {filtered.length === PROJECTS.length
            ? `Всего проектов: ${PROJECTS.length}`
            : `Показано ${filtered.length} из ${PROJECTS.length} проектов`}
        </p>
      </header>

      <div
        role="group"
        aria-label="Фильтр по статусу"
        style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
      >
        {STATUS_ORDER.map((status) => {
          const isActive = statuses.includes(status);
          return (
            <JxChip
              key={status}
              active={isActive}
              removable={isActive}
              onRemove={() => toggleStatus(status)}
              role="button"
              tabIndex={0}
              aria-pressed={isActive}
              onClick={() => toggleStatus(status)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  toggleStatus(status);
                }
              }}
            >
              {STATUS_META[status].label}
            </JxChip>
          );
        })}
      </div>

      {visible.length === 0 ? (
        <JxEmptyState
          title="Под фильтры ничего не попало"
          message="Ни один проект не подходит под выбранные статусы. Снимите часть фильтров, чтобы увидеть список."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul
            style={{
              listStyle: 'none',
              margin: 0,
              padding: 0,
              display: 'flex',
              flexDirection: 'column',
            }}
          >
            {visible.map((project, index) => {
              const percent = Math.round((project.used / project.quota) * 100);
              const meta = STATUS_META[project.status];
              return (
                <li
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '16px',
                    padding: '12px 4px',
                    borderTop: index === 0 ? 'none' : '1px solid var(--jx-rule)',
                  }}
                >
                  <JxProgressCircle value={percent} max={100} showValue />
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div
                      style={{
                        fontSize: '15px',
                        color: 'var(--jx-text)',
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                      }}
                    >
                      {project.name}
                    </div>
                    <div
                      style={{
                        fontSize: '13px',
                        color: 'var(--jx-text-2)',
                        fontFamily: 'var(--jx-font-mono)',
                      }}
                    >
                      {project.used} / {project.quota} квоты
                    </div>
                  </div>
                  <JxBadge tone={meta.tone} dot>
                    {meta.label}
                  </JxBadge>
                </li>
              );
            })}
          </ul>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </section>
  );
}

